#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using Cysharp.Threading.Tasks;
using MVZ2.IO;
using MVZ2.Managers;
using MVZ2.Resources;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using NGettext;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Localization
{
    public class ResourcePackReaderZipV1 : ResourcePackReaderV1, IResourcePackReaderZip
    {
        public ResourcePackReaderZipV1(MainManager main) : base(main)
        {
        }
        public override UniTask<ResourcePack?> ReadPack(string key, string path)
        {
            using var stream = File.Open(path, FileMode.Open);
            return ReadPack(key, stream);
        }
        public async UniTask<ResourcePack?> ReadPack(string key, byte[] bytes)
        {
            using var memory = new MemoryStream(bytes);
            return await ReadPack(key, memory);
        }
        public async UniTask<ResourcePack?> ReadPack(string key, Stream stream)
        {
            try
            {
                using var archive = new ZipArchive(stream);
                var packReadData = await UniTask.RunOnThreadPool(() => ReadPackData(key, archive));
                if (packReadData == null)
                    return null;
                var pack = new ResourcePack(key);

                await UniTask.SwitchToMainThread();

                ApplyReadData(pack, packReadData, (p, n) => ReadTexture2DZip(archive, p, n));

                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包Zip失败：{e}");
                return null;
            }
        }
        private async UniTask<PackReadData> ReadPackData(string key, ZipArchive archive)
        {
            // 新建一个资源包实例。
            var packData = new PackReadData(key);

            // manifest条目。
            var manifestEntry = archive.GetEntry(MANIFEST_FILENAME);

            // 将manifest读取到内存。
            var manifest = await LoadManifest(manifestEntry);
            if (manifest == null)
            {
                throw new FileNotFoundException($"The file {MANIFEST_FILENAME} in resource pack {key} is missing!");
            }
            // 从manifest中读取资源包内容。
            await ReadPackFromManifest(archive, manifest, packData, key);
            return packData;
        }
        private async UniTask<ResourcePackManifest?> LoadManifest(ZipArchiveEntry entry)
        {
            // 加载Sprite Manifest文件。
            if (entry == null)
                return null;
            var manifestJson = await entry.ReadStringAsync(Encoding.UTF8);
            return JsonConvert.DeserializeObject<ResourcePackManifest>(manifestJson);
        }
        private async UniTask ReadPackFromManifest(ZipArchive archive, ResourcePackManifest manifest, PackReadData pack, string key)
        {
            // 加载翻译文件。
            await ReadPackCatalogsFromManifest(archive, manifest, pack);

            // 加载贴图。
            ReadPackSpritesFromManifest(archive, manifest, pack, key);
        }

        private async UniTask ReadPackCatalogsFromManifest(ZipArchive archive, ResourcePackManifest manifest, PackReadData pack)
        {
            if (manifest.localization == null)
                return;

            if (manifest.localization.languages != null)
            {
                foreach (var language in manifest.localization.languages)
                {
                    // 语言代码。
                    var code = language.code;
                    if (string.IsNullOrEmpty(code))
                        continue;

                    Dictionary<string, Catalog> catalogDirectroy = new Dictionary<string, Catalog>();
                    if (language.catalogs != null)
                    {
                        foreach (var relativePath in language.catalogs)
                        {
                            // 获取catalog的路径，并加载。
                            var catalogPath = Path.Combine("assets", relativePath).Replace("/", "\\");
                            var catalogEntry = archive.GetEntry(catalogPath);
                            var catalog = await catalogEntry.ReadCatalogAsync(code);

                            // 将加载后的catalog注册。
                            var filenameWithoutExt = Path.GetFileNameWithoutExtension(catalogPath);
                            catalogDirectroy.Add(filenameWithoutExt, catalog);
                        }
                    }
                    pack.catalogs.Add(code, catalogDirectroy);
                }
            }
        }

        private void ReadPackSpritesFromManifest(ZipArchive archive, ResourcePackManifest manifest, PackReadData pack, string key)
        {
            // 加载贴图
            if (manifest.textures == null)
                return;

            var generatedCategory = GetLanguagePackSpriteCategory(key);

            foreach (var packTexture in manifest.textures)
            {
                if (string.IsNullOrEmpty(packTexture.texture))
                    continue;
                
                if (string.IsNullOrEmpty(packTexture.key))
                {
                    Log.LogWarning($"Missing resource pack texture key {packTexture.texture}.");
                    continue;
                }

                // 获取贴图路径。
                var texturePath = Path.Combine("assets", packTexture.texture).Replace("\\", "/");
                var textureID = NamespaceID.Parse(packTexture.key, Main.BuiltinNamespace);

                // 获取ID和图片标签。
                var splitTexturePaths = Path.ChangeExtension(packTexture.texture, string.Empty).TrimEnd('.').Split('/', '\\');
                string nsp, textureId;
                if (splitTexturePaths.Length > 1)
                {
                    nsp = splitTexturePaths[0];
                    textureId = string.Join("/", splitTexturePaths.Skip(1));
                }
                else
                {
                    nsp = string.Empty;
                    textureId = string.Join("/", splitTexturePaths);
                }
                SpriteHelper.ParseIDAndTags(textureId, out textureId, out var tags);

                // 加载贴图。
                var textureEntry = new TextureEntry(textureID, texturePath)
                {
                    filterMode = (FilterMode)packTexture.filter
                };
                var slices = packTexture.slices;
                if (slices != null)
                {
                    for (int i = 0; i < slices.Length; i++)
                    {
                        var slice = slices[i];
                        var sliceKey = slice.key;
                        SpriteReference? spriteRef = null;
                        if (sliceKey != null && SpriteReference.TryParse(sliceKey, Main.BuiltinNamespace, out var sprRef))
                        {
                            spriteRef = sprRef;
                        }
                        if (spriteRef == null)
                        {
                            spriteRef = new SpriteReference(textureID, i);
                        }
                        var spriteKey = new SpriteLookupKey(spriteRef, slice.tags ?? tags);
                        var sliceData = new SliceData(spriteKey)
                        {
                            border = new Vector4(slice.borderLeft, slice.borderBottom, slice.borderRight, slice.borderTop),
                            extrude = 0,
                            meshType = slice.fullRect ? SpriteMeshType.FullRect : SpriteMeshType.Tight,
                            pivot = new Vector2(slice.pivotX, slice.pivotY),
                            pixelsPerUnit = 100,
                            rect = new Rect(slice.x, slice.y, slice.width, slice.height),
                            single = slice.single,
                            spriteKey = spriteKey,
                        };
                        textureEntry.slices.Add(sliceData);
                    }
                }
                pack.textureEntries.Add(textureEntry);
            }
        }
        private Texture2D? ReadTexture2DZip(ZipArchive archive, string path, string name = "texture2D")
        {
            var textureEntry = archive.Entries.FirstOrDefault(e => e.FullName.Replace("\\", "/") == path);

            if (textureEntry == null)
                return null;
            var bytes = textureEntry.ReadBytes();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
    }
}
